# ! [doc = " # The Rust Prelude"] # ! [doc = ""] # ! [doc = " Rust comes with a variety of things in its standard library. However, if"] # ! [doc = " you had to manually import every single thing that you used, it would be"] # ! [doc = " very verbose. But importing a lot of things that a program never uses isn't"] # ! [doc = " good either. A balance needs to be struck."] # ! [doc = ""] # ! [doc = " The *prelude* is the list of things that Rust automatically imports into"] # ! [doc = " every Rust program. It's kept as small as possible, and is focused on"] # ! [doc = " things, particularly traits, which are used in almost every single Rust"] # ! [doc = " program."] # ! [doc = ""] # ! [doc = " # Other preludes"] # ! [doc = ""] # ! [doc = " Preludes can be seen as a pattern to make using multiple types more"] # ! [doc = " convenient. As such, you'll find other preludes in the standard library,"] # ! [doc = " such as [`std::io::prelude`]. Various libraries in the Rust ecosystem may"] # ! [doc = " also define their own preludes."] # ! [doc = ""] # ! [doc = " [`std::io::prelude`]: crate::io::prelude"] # ! [doc = ""] # ! [doc = " The difference between 'the prelude' and these other preludes is that they"] # ! [doc = " are not automatically `use`'d, and must be imported manually. This is still"] # ! [doc = " easier than importing all of their constituent components."] # ! [doc = ""] # ! [doc = " # Prelude contents"] # ! [doc = ""] # ! [doc = " The items included in the prelude depend on the edition of the crate."] # ! [doc = " The first version of the prelude is used in Rust 2015 and Rust 2018,"] # ! [doc = " and lives in [`std::prelude::v1`]."] # ! [doc = " [`std::prelude::rust_2015`] and [`std::prelude::rust_2018`] re-export this prelude."] # ! [doc = " It re-exports the following:"] # ! [doc = ""] # ! [doc = " * <code>[std::marker]::{[Copy], [Send], [Sized], [Sync], [Unpin]}</code>,"] # ! [doc = "   marker traits that indicate fundamental properties of types."] # ! [doc = " * <code>[std::ops]::{[Fn], [FnMut], [FnOnce]}</code>, and their analogous"] # ! [doc = "   async traits, <code>[std::ops]::{[AsyncFn], [AsyncFnMut], [AsyncFnOnce]}</code>."] # ! [doc = " * <code>[std::ops]::[Drop]</code>, for implementing destructors."] # ! [doc = " * <code>[std::mem]::[drop]</code>, a convenience function for explicitly"] # ! [doc = "   dropping a value."] # ! [doc = " * <code>[std::mem]::{[size_of], [size_of_val]}</code>, to get the size of"] # ! [doc = "   a type or value."] # ! [doc = " * <code>[std::mem]::{[align_of], [align_of_val]}</code>, to get the"] # ! [doc = "   alignment of a type or value."] # ! [doc = " * <code>[std::boxed]::[Box]</code>, a way to allocate values on the heap."] # ! [doc = " * <code>[std::borrow]::[ToOwned]</code>, the conversion trait that defines"] # ! [doc = "   [`to_owned`], the generic method for creating an owned type from a"] # ! [doc = "   borrowed type."] # ! [doc = " * <code>[std::clone]::[Clone]</code>, the ubiquitous trait that defines"] # ! [doc = "   [`clone`][Clone::clone], the method for producing a copy of a value."] # ! [doc = " * <code>[std::cmp]::{[PartialEq], [PartialOrd], [Eq], [Ord]}</code>, the"] # ! [doc = "   comparison traits, which implement the comparison operators and are often"] # ! [doc = "   seen in trait bounds."] # ! [doc = " * <code>[std::convert]::{[AsRef], [AsMut], [Into], [From]}</code>, generic"] # ! [doc = "   conversions, used by savvy API authors to create overloaded methods."] # ! [doc = " * <code>[std::default]::[Default]</code>, types that have default values."] # ! [doc = " * <code>[std::iter]::{[Iterator], [Extend], [IntoIterator], [DoubleEndedIterator], [ExactSizeIterator]}</code>,"] # ! [doc = "   iterators of various"] # ! [doc = "   kinds."] # ! [doc = " * <code>[std::option]::[Option]::{[self][Option], [Some], [None]}</code>, a"] # ! [doc = "   type which expresses the presence or absence of a value. This type is so"] # ! [doc = "   commonly used, its variants are also exported."] # ! [doc = " * <code>[std::result]::[Result]::{[self][Result], [Ok], [Err]}</code>, a type"] # ! [doc = "   for functions that may succeed or fail. Like [`Option`], its variants are"] # ! [doc = "   exported as well."] # ! [doc = " * <code>[std::string]::{[String], [ToString]}</code>, heap-allocated strings."] # ! [doc = " * <code>[std::vec]::[Vec]</code>, a growable, heap-allocated vector."] # ! [doc = ""] # ! [doc = " The prelude used in Rust 2021, [`std::prelude::rust_2021`], includes all of the above,"] # ! [doc = " and in addition re-exports:"] # ! [doc = ""] # ! [doc = " * <code>[std::convert]::{[TryFrom], [TryInto]}</code>."] # ! [doc = " * <code>[std::iter]::[FromIterator]</code>."] # ! [doc = ""] # ! [doc = " The prelude used in Rust 2024, [`std::prelude::rust_2024`], includes all of the above,"] # ! [doc = " and in addition re-exports:"] # ! [doc = ""] # ! [doc = " * <code>[std::future]::{[Future], [IntoFuture]}</code>."] # ! [doc = ""] # ! [doc = " [std::borrow]: crate::borrow"] # ! [doc = " [std::boxed]: crate::boxed"] # ! [doc = " [std::clone]: crate::clone"] # ! [doc = " [std::cmp]: crate::cmp"] # ! [doc = " [std::convert]: crate::convert"] # ! [doc = " [std::default]: crate::default"] # ! [doc = " [std::future]: crate::future"] # ! [doc = " [std::iter]: crate::iter"] # ! [doc = " [std::marker]: crate::marker"] # ! [doc = " [std::mem]: crate::mem"] # ! [doc = " [std::ops]: crate::ops"] # ! [doc = " [std::option]: crate::option"] # ! [doc = " [`std::prelude::v1`]: v1"] # ! [doc = " [`std::prelude::rust_2015`]: rust_2015"] # ! [doc = " [`std::prelude::rust_2018`]: rust_2018"] # ! [doc = " [`std::prelude::rust_2021`]: rust_2021"] # ! [doc = " [`std::prelude::rust_2024`]: rust_2024"] # ! [doc = " [std::result]: crate::result"] # ! [doc = " [std::slice]: crate::slice"] # ! [doc = " [std::string]: crate::string"] # ! [doc = " [std::vec]: mod@crate::vec"] # ! [doc = " [`to_owned`]: crate::borrow::ToOwned::to_owned"] # ! [doc = " [book-closures]: ../../book/ch13-01-closures.html"] # ! [doc = " [book-dtor]: ../../book/ch15-03-drop.html"] # ! [doc = " [book-enums]: ../../book/ch06-01-defining-an-enum.html"] # ! [doc = " [book-iter]: ../../book/ch13-02-iterators.html"] # ! [doc = " [Future]: crate::future::Future"] # ! [doc = " [IntoFuture]: crate::future::IntoFuture"] # ! [cfg_attr (rustfmt , rustfmt :: skip)] # ! [stable (feature = "rust1" , since = "1.0.0")] use split_decls_genesis :: ourprelude :: * ; pub mod v1 ; #[doc = " The 2015 version of the prelude of The Rust Standard Library."] #[doc = ""] #[doc = " See the [module-level documentation](self) for more."] #[stable (feature = "prelude_2015" , since = "1.55.0")] pub mod rust_2015 { #[stable (feature = "prelude_2015" , since = "1.55.0")] #[doc (no_inline)] pub use super :: v1 :: * ; } #[doc = " The 2018 version of the prelude of The Rust Standard Library."] #[doc = ""] #[doc = " See the [module-level documentation](self) for more."] #[stable (feature = "prelude_2018" , since = "1.55.0")] pub mod rust_2018 { #[stable (feature = "prelude_2018" , since = "1.55.0")] #[doc (no_inline)] pub use super :: v1 :: * ; } #[doc = " The 2021 version of the prelude of The Rust Standard Library."] #[doc = ""] #[doc = " See the [module-level documentation](self) for more."] #[stable (feature = "prelude_2021" , since = "1.55.0")] pub mod rust_2021 { #[stable (feature = "prelude_2021" , since = "1.55.0")] #[doc (no_inline)] pub use super :: v1 :: * ; #[stable (feature = "prelude_2021" , since = "1.55.0")] #[doc (no_inline)] pub use core :: prelude :: rust_2021 :: * ; } #[doc = " The 2024 version of the prelude of The Rust Standard Library."] #[doc = ""] #[doc = " See the [module-level documentation](self) for more."] #[stable (feature = "prelude_2024" , since = "1.85.0")] pub mod rust_2024 { #[stable (feature = "rust1" , since = "1.0.0")] #[doc (no_inline)] pub use super :: v1 :: * ; #[stable (feature = "prelude_2024" , since = "1.85.0")] #[doc (no_inline)] pub use core :: prelude :: rust_2024 :: * ; } #[doc = " The Future version of the prelude of The Rust Standard Library."] #[doc = ""] #[doc = " See the [module-level documentation](self) for more."] #[doc (hidden)] #[unstable (feature = "prelude_future" , issue = "none")] pub mod rust_future { #[stable (feature = "rust1" , since = "1.0.0")] #[doc (no_inline)] pub use super :: v1 :: * ; #[unstable (feature = "prelude_next" , issue = "none")] #[doc (no_inline)] pub use core :: prelude :: rust_future :: * ; }